                '#include <fcntl.h>\n'
                '#include <errno.h>\n'
                '#include <limits.h>\n'
                '#include <signal.h>\n'
                '#include <time.h>\n'
                '#include <dirent.h>\n'
                '#include <sys/stat.h>\n'
                '#include <sys/types.h>\n'
                '#include <sys/wait.h>\n'
                '\n'
                'static char *mktmp(void) {\n'
                '    static char d[64];\n'
                '    strcpy(d, "/tmp/uXXXXXX");\n'
                '    return mkdtemp(d);\n'
                '}\n'
                '\n'
                'static void put(const char *path, const char *data) {\n'
                '    int fd = open(path, O_CREAT | O_TRUNC | O_WRONLY, 0644);\n'
                '    if (fd >= 0) {\n'
                '        if (write(fd, data, strlen(data)) < 0) {}\n'
                '        close(fd);\n'
