                'static void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n'
                '\n'
                'int main(void) {\n'
                '    setup();\n'
                '    struct inode f = {1000, 100, S_IFREG | 0640}, x = {0, 0, S_IFREG | 0600}, d = {0, 0, '
                'S_IFDIR | 0700}, lock = {1000, 100, S_IFREG | 0070};\n'
                '    struct cred owner = {1000, 1000, {0}, 0}, member = {2000, 2000, {100}, 1}, other = '
                '{3000, 3000, {5, 6}, 2}, root = {0, 0, {0}, 0};\n'
                '    int w[] = {4, 2, 1, 6};\n'
                '    struct { struct inode *i; struct cred *c; const char *n; } cs[] = {{&f, &owner, '
                '"owner"}, {&f, &member, "member"}, {&f, &other, "other"}, {&x, &root, "root-x"}, {&d, '
                '&root, "root-dir"}, {&lock, &owner, "locked-owner"}, {&lock, &member, "locked-member"}};\n'
                '    for (unsigned k = 0; k < sizeof cs / sizeof cs[0]; k++) {\n'
                '        printf("%s:", cs[k].n);\n'
                '        for (int j = 0; j < 4; j++) printf(" %d", may_access(cs[k].i, cs[k].c, w[j]));\n'
