                'blk, sizeof blk) < 0) {} }\n'
                '    close(fd);\n'
                '    printf("%ld\\n", copy_file(a, b));\n'
                '    struct stat sa, sb;\n'
                '    stat(a, &sa); stat(b, &sb);\n'
                '    printf("%d %o\\n", (long)sa.st_size == (long)sb.st_size, sb.st_mode & 0777);\n'
                '    char x[16], y[16];\n'
                '    int f1 = open(a, O_RDONLY), f2 = open(b, O_RDONLY);\n'
                '    int same = 1;\n'
                '    for (off_t o = 0; o < sa.st_size; o += 99991) {\n'
