                '    setup();\n'
                '    printf("%ld %ld\\n", run_atomic(4, 100000), run_atomic(1, 5));\n'
                '    static int v[400000];\n'
                '    unsigned s = 3;\n'
                '    int best = INT_MIN;\n'
                '    for (int i = 0; i < 400000; i++) { s = s * 1664525u + 1013904223u; v[i] = (int)(s >> 4) '
