                 'parse_mem_max("x"));\n'
                 '    long q, p;\n'
                 '    printf("%d %ld %ld\\n", parse_cpu_max("50000 100000\\n", &q, &p), q, p);\n'
                 '    printf("%d %ld %ld\\n", parse_cpu_max("max 100000", &q, &p), q, p);\n'
                 '    printf("%d\\n", parse_cpu_max("garbage", &q, &p));\n'
                 '    printf("%ld %ld %ld %ld\\n", cpu_percent("50000 100000"), cpu_percent("200000 '
